import{_ as a,o,c as n,a5 as e}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"737-【以管理员身份运行程序】批量以txt中关键词分类创建文件夹并搜索带有关键词文件创建软链接","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["为文件创建软连接","批量创建软连接","软连接"]},"headers":[],"relativePath":"md/文件及文件夹批处理/737-【以管理员身份运行程序】批量以txt中关键词分类创建文件夹并搜索带有关键词文件创建软链接.md","filePath":"md/文件及文件夹批处理/737-【以管理员身份运行程序】批量以txt中关键词分类创建文件夹并搜索带有关键词文件创建软链接.md"}'),r={name:"md/文件及文件夹批处理/737-【以管理员身份运行程序】批量以txt中关键词分类创建文件夹并搜索带有关键词文件创建软链接.md"};function s(_,t,p,l,i,h){return o(),n("div",null,[...t[0]||(t[0]=[e('<h3 id="程序介绍" tabindex="-1">程序介绍 <a class="header-anchor" href="#程序介绍" aria-label="Permalink to &quot;程序介绍&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250424101319174546079914996.png" alt=""></p><p>批量以txt中关键词在目标文件夹A中创建文件夹，并在目标文件夹B内搜索带有关键词的文件，在目标文件夹下创建的文件夹内为文件创建软连接。</p><p>关键词如果有一个，则只创建一个文件夹，创建的文件夹格式为：001_关键词</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250424111546174546454664337.png" alt=""></p><h3 id="软连接说明" tabindex="-1">软连接说明 <a class="header-anchor" href="#软连接说明" aria-label="Permalink to &quot;软连接说明&quot;">​</a></h3><p>软连接（Symbolic Link，简称 symlink）是一种特殊的文件类型，它类似于快捷方式。软连接本质上是指向另一个文件或目录的引用，而不是文件或目录本身。</p><h3 id="软连接特点" tabindex="-1">软连接特点： <a class="header-anchor" href="#软连接特点" aria-label="Permalink to &quot;软连接特点：&quot;">​</a></h3><ul><li><strong>指向路径</strong>：软连接本身是一个文件，它保存着目标文件或目录的路径。当访问软连接时，操作系统会自动将其指向的目标文件或目录打开。</li><li><strong>可以跨文件系统</strong>：软连接可以指向同一文件系统中的文件，也可以指向不同文件系统中的文件。</li><li><strong>目标文件可以不存在</strong>：软连接可以指向一个尚不存在的文件或目录，这种情况下，软连接就成为“悬挂链接”或“死链接”，即指向一个无效的目标。</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>必须要以管理员身份运行程序，以非管理员身份运行时是无法创建软连接的</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250424112334174546501472516.png" alt=""></p><p>1、需要创建文件夹的路径：为在哪里（哪个文件夹下）创建软连接</p><p>2、关键词文件路径：为txt文档路径，txt中每行一个关键词，关键词包含在文件名中</p><p>3、搜索文件所在文件夹路径：为需要创建软连接的文件所在文件夹路径</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250424101319174546079914996.png" alt=""></p><h3 id="效果图展示" tabindex="-1">效果图展示 <a class="header-anchor" href="#效果图展示" aria-label="Permalink to &quot;效果图展示&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250424111458174546449823239.png" alt=""></p><h3 id="程序适用环境" tabindex="-1">程序适用环境 <a class="header-anchor" href="#程序适用环境" aria-label="Permalink to &quot;程序适用环境&quot;">​</a></h3><p>win7及以上64位操作系统</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1755.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1755.html</a></p>',22)])])}const d=a(r,[["render",s]]);export{g as __pageData,d as default};
